// Copies the SQL migrations generated by drizzle-kit into Netlify Database's migrations folder.
// Netlify applies the files in netlify/database/migrations during each deploy; every other host
// applies the same SQL from ./drizzle when the app starts. Run via `npm run db:generate`.
import fs from "node:fs";
import path from "node:path";

const from = path.resolve("drizzle");
const to = path.resolve("netlify/database/migrations");
fs.mkdirSync(to, { recursive: true });
let copied = 0;
for (const name of fs.readdirSync(from).filter((f) => f.endsWith(".sql")).sort()) {
  const target = path.join(to, name);
  const sql = fs.readFileSync(path.join(from, name), "utf8");
  if (fs.existsSync(target)) {
    // Applied migrations must never change (Netlify rejects edited files), so only new files are written.
    if (fs.readFileSync(target, "utf8") !== sql) console.warn(`! ${name} differs from the copy in netlify/database/migrations — not overwritten`);
    continue;
  }
  fs.writeFileSync(target, sql);
  copied++;
}
console.log(`netlify/database/migrations: ${copied} new migration file(s)`);
